//! Byte-oriented port of the C++ "inflection" string library.
//!
//! All functions operate on raw byte slices (`&[u8]`) and return `Vec<u8>`,
//! mirroring the C-locale, ASCII-only semantics of the original C++ code.
//! Bytes >= 0x80 pass through untouched everywhere except in
//! [`parameterize`], where they are dropped.

pub mod atoi;
pub mod camelize;
pub mod ordinalize;
pub mod parameterize;
pub mod pluralize;
pub mod titlecase;
pub mod truncate;

/// ASCII uppercase of a single byte (C-locale `toupper`): only `a`-`z` change.
pub(crate) fn to_upper(b: u8) -> u8 {
    if b.is_ascii_lowercase() {
        b - 32
    } else {
        b
    }
}

/// ASCII lowercase of a single byte (C-locale `tolower`): only `A`-`Z` change.
pub(crate) fn to_lower(b: u8) -> u8 {
    if b.is_ascii_uppercase() {
        b + 32
    } else {
        b
    }
}

//! `atoi` with glibc `strtol` semantics: whitespace skip, optional sign,
//! decimal digits, i64 saturation, then truncation to i32.

/// Parse `s` like C `atoi` backed by glibc `strtol`.
///
/// 1. Skip leading whitespace: space, `\t`, `\n`, `\v` (0x0b), `\f` (0x0c), `\r`.
/// 2. Optional single `+` or `-`.
/// 3. Consume decimal digits; stop at the first non-digit. No digits => 0.
/// 4. Accumulate as i64 with saturation (`i64::MAX` / `i64::MIN` on overflow).
/// 5. Truncate the saturated i64 to i32 (two's complement low 32 bits).
pub fn atoi(s: &[u8]) -> i32 {
    let mut i = 0usize;

    // 1. Skip leading whitespace.
    while i < s.len() && matches!(s[i], b' ' | b'\t' | b'\n' | 0x0b | 0x0c | b'\r') {
        i += 1;
    }

    // 2. Optional sign.
    let negative = if i < s.len() && (s[i] == b'+' || s[i] == b'-') {
        let neg = s[i] == b'-';
        i += 1;
        neg
    } else {
        false
    };

    // 3-4. Consume digits with i64 saturation. Accumulate negatively so that
    // the full i64 range (including i64::MIN) is representable.
    let mut value: i64 = 0;
    let mut saturated = false;
    while i < s.len() && s[i].is_ascii_digit() {
        let digit = (s[i] - b'0') as i64;
        i += 1;
        if saturated {
            continue;
        }
        match value
            .checked_mul(10)
            .and_then(|v| v.checked_sub(digit))
        {
            Some(v) => value = v,
            None => {
                value = i64::MIN;
                saturated = true;
            }
        }
    }

    let result = if negative { value } else { value.saturating_neg() };
    // 5. Truncate to i32.
    result as i32
}

//! `ordinalize`: format an i32 in canonical decimal with an English suffix.

/// Return the ordinal string for `n`, e.g. `1st`, `12th`, `23rd`, `-1th`.
///
/// Suffix rules (Rust `%` keeps the sign of the dividend, same as C++, so
/// negative numbers never hit the 11/12/13 or 1/2/3 branches and all get
/// "th"):
/// - `n % 100` is 11, 12 or 13 => "th"
/// - else `n % 10` is 1 => "st", 2 => "nd", 3 => "rd", otherwise "th"
pub fn ordinalize(n: i32) -> Vec<u8> {
    let suffix = if matches!(n % 100, 11 | 12 | 13) {
        "th"
    } else {
        match n % 10 {
            1 => "st",
            2 => "nd",
            3 => "rd",
            _ => "th",
        }
    };
    let mut out = n.to_string().into_bytes();
    out.extend_from_slice(suffix.as_bytes());
    out
}

//! `pluralize` / `is_plural` with a fixed uncountable list and a single
//! append-`s` rule.

/// Fixed, case-sensitive, exact-match uncountable list.
pub const UNCOUNTABLES: [&[u8]; 10] = [
    b"sheep",
    b"fish",
    b"information",
    b"equipment",
    b"money",
    b"rice",
    b"police",
    b"jeans",
    b"series",
    b"species",
];

/// Whether `word` exactly matches an uncountable entry.
pub fn is_uncountable(word: &[u8]) -> bool {
    UNCOUNTABLES.iter().any(|&u| u == word)
}

/// Pluralize `word`: empty or uncountable words are returned unchanged,
/// anything else gets a trailing `s`. No other rules.
pub fn pluralize(word: &[u8]) -> Vec<u8> {
    if word.is_empty() || is_uncountable(word) {
        word.to_vec()
    } else {
        let mut out = word.to_vec();
        out.push(b's');
        out
    }
}

/// A word "is plural" iff it is non-empty, ends in `s`, and is not an exact
/// uncountable match.
pub fn is_plural(word: &[u8]) -> bool {
    !word.is_empty() && word[word.len() - 1] == b's' && !is_uncountable(word)
}

//! `camelize` with this binary's (inverted) flag semantics.

use crate::to_upper;

/// Camelize `word`.
///
/// Only `b'_'` is a separator and is deleted; every other byte passes
/// through. For each kept byte at ORIGINAL index `i`, ASCII-uppercase it iff:
/// - `uppercase_first == false` (lower variant): `i > 0 && word[i-1] == b'_'`
/// - `uppercase_first == true` (upper variant): `i == 0 || word[i-1] == b'_'`
///
/// Nothing is ever lowercased.
pub fn camelize(word: &[u8], uppercase_first: bool) -> Vec<u8> {
    let mut out = Vec::with_capacity(word.len());
    for (i, &b) in word.iter().enumerate() {
        if b == b'_' {
            continue;
        }
        let up = if uppercase_first {
            i == 0 || word[i - 1] == b'_'
        } else {
            i > 0 && word[i - 1] == b'_'
        };
        out.push(if up { to_upper(b) } else { b });
    }
    out
}

//! `titleize` and `capitalize`.

use crate::{to_lower, to_upper};

/// Titleize `word`: ASCII-lowercase every byte, then ASCII-uppercase byte 0
/// and any byte whose immediately preceding byte is a space (0x20 only).
pub fn titleize(word: &[u8]) -> Vec<u8> {
    let mut out: Vec<u8> = word.iter().map(|&b| to_lower(b)).collect();
    for i in 0..out.len() {
        if i == 0 || out[i - 1] == b' ' {
            out[i] = to_upper(out[i]);
        }
    }
    out
}

/// Capitalize `word`: empty stays empty; otherwise ASCII-uppercase byte 0 and
/// ASCII-lowercase all remaining bytes.
pub fn capitalize(word: &[u8]) -> Vec<u8> {
    if word.is_empty() {
        return Vec::new();
    }
    let mut out = Vec::with_capacity(word.len());
    out.push(to_upper(word[0]));
    out.extend(word[1..].iter().map(|&b| to_lower(b)));
    out
}

//! `truncate` with raw BYTE semantics — may split multi-byte UTF-8.

/// Truncate `word` to `length` bytes, replacing the tail with `omission`.
///
/// If `word.len() > length`, return `word[0 .. length - omission.len()]`
/// followed by `omission` (raw byte slice; may split a UTF-8 character).
/// Otherwise return `word` unchanged (strict `>` — exactly `length` bytes is
/// unchanged).
pub fn truncate(word: &[u8], length: usize, omission: &[u8]) -> Vec<u8> {
    if word.len() > length {
        let keep = length - omission.len();
        let mut out = Vec::with_capacity(length);
        out.extend_from_slice(&word[..keep]);
        out.extend_from_slice(omission);
        out
    } else {
        word.to_vec()
    }
}

//! `parameterize`: ASCII-only slugification, no transliteration.

use crate::to_lower;

/// Parameterize `word` with separator byte `sep`.
///
/// 1. Per byte: `A`-`Z` => lowercase; `a`-`z` and `0`-`9` => keep;
///    space (0x20) => `sep`; everything else (all punctuation, tabs,
///    newlines, all bytes >= 0x80) => deleted.
/// 2. Trim leading/trailing `sep` bytes from the result. Interior `sep`s are
///    NOT collapsed.
pub fn parameterize(word: &[u8], sep: u8) -> Vec<u8> {
    let mut out = Vec::with_capacity(word.len());
    for &b in word {
        match b {
            b'A'..=b'Z' => out.push(to_lower(b)),
            b'a'..=b'z' | b'0'..=b'9' => out.push(b),
            b' ' => out.push(sep),
            _ => {}
        }
    }
    while out.first() == Some(&sep) {
        out.remove(0);
    }
    while out.last() == Some(&sep) {
        out.pop();
    }
    out
}

//! Entry point mirroring the C++ test11.cpp `main`.
//!
//! Usage: `test11 <num_str> <word>` — prints 11 lines of inflection results.
//! With fewer than 2 user arguments (argc <= 2) it prints nothing and exits 0.

use std::io::Write;
use std::os::unix::ffi::OsStrExt;

use inflection::atoi::atoi;
use inflection::camelize::camelize;
use inflection::ordinalize::ordinalize;
use inflection::parameterize::parameterize;
use inflection::pluralize::{is_plural, pluralize};
use inflection::titlecase::{capitalize, titleize};
use inflection::truncate::truncate;

fn main() {
    // Raw-byte argv (may contain non-UTF-8 bytes).
    let args: Vec<Vec<u8>> = std::env::args_os()
        .map(|a| a.as_bytes().to_vec())
        .collect();

    // argc <= 2: fewer than 2 user args — print nothing, exit 0.
    if args.len() <= 2 {
        return;
    }

    let num = atoi(&args[1]);
    let word = &args[2];

    let stdout = std::io::stdout();
    let mut out = stdout.lock();

    let mut emit = |line: &[u8]| {
        out.write_all(line).expect("write to stdout failed");
        out.write_all(b"\n").expect("write to stdout failed");
    };

    emit(&pluralize(word)); // 1
    emit(&ordinalize(num)); // 2
    emit(&camelize(word, false)); // 3: lower variant (first byte NOT uppercased)
    emit(&camelize(word, true)); // 4: upper variant (first byte uppercased)
    emit(&titleize(word)); // 5
    emit(&capitalize(word)); // 6
    emit(&truncate(word, 5, b"...")); // 7
    emit(&truncate(word, 10, b"~")); // 8
    emit(&parameterize(word, b'-')); // 9
    emit(&parameterize(word, b'_')); // 10
    emit(if is_plural(word) { b"1" } else { b"0" }); // 11
}
